 const string Root="Assets/_Anseong/Art/Environment/Assets/Tetrapod";
 static void Folder(string p){if(AssetDatabase.IsValidFolder(p))return;var parent=Path.GetDirectoryName(p).Replace('\\','/');Folder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(p));}
 static Material Mat(string name,Color color){var previous=AssetDatabase.LoadAssetAtPath<Material>(Root+"/"+name+".mat");if(previous)return previous;var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=color;m.SetFloat("_Smoothness",.05f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,Root+"/"+name+".mat");return m;}
 static Mesh Geometry(){var vertices=new List<Vector3>();var triangles=new List<int>();void Triangle(Vector3 a,Vector3 b,Vector3 c){int n=vertices.Count;vertices.AddRange(new[]{a,b,c});triangles.AddRange(new[]{n,n+1,n+2});}void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d){Triangle(a,b,c);Triangle(a,c,d);}var align=Quaternion.FromToRotation(new Vector3(1,1,1).normalized,Vector3.up);
  foreach(var raw in new[]{new Vector3(1,1,1),new Vector3(1,-1,-1),new Vector3(-1,1,-1),new Vector3(-1,-1,1)}){var axis=align*raw.normalized;var side=Vector3.Cross(axis,Vector3.forward).normalized;if(side.sqrMagnitude<.01f)side=Vector3.right;var other=Vector3.Cross(axis,side);Vector3 Point(float distance,float radius,int i){float a=i*Mathf.PI*2/12;return axis*distance+(side*Mathf.Cos(a)+other*Mathf.Sin(a))*radius;}
   for(int i=0;i<12;i++){Quad(Point(.25f,.78f,i),Point(.25f,.78f,i+1),Point(2.05f,.44f,i+1),Point(2.05f,.44f,i));Quad(Point(2.05f,.44f,i),Point(2.05f,.44f,i+1),Point(2.17f,.38f,i+1),Point(2.17f,.38f,i));Triangle(axis*2.17f,Point(2.17f,.38f,i),Point(2.17f,.38f,i+1));}
  }
  Vector3 Sphere(int row,int col){float pitch=Mathf.PI*row/6,y=Mathf.Cos(pitch)*.85f,r=Mathf.Sin(pitch)*.85f,a=col*Mathf.PI*2/12;return new Vector3(Mathf.Cos(a)*r,y,Mathf.Sin(a)*r);}
  for(int row=0;row<6;row++)for(int col=0;col<12;col++){if(row==0)Triangle(Sphere(row,col),Sphere(row+1,col+1),Sphere(row+1,col));else if(row==5)Triangle(Sphere(row,col),Sphere(row,col+1),Sphere(row+1,col));else Quad(Sphere(row,col),Sphere(row,col+1),Sphere(row+1,col+1),Sphere(row+1,col));}
  var mesh=new Mesh{name="Tetrapod"};mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();mesh.RecalculateBounds();var v=mesh.vertices;float min=mesh.bounds.min.y;for(int i=0;i<v.Length;i++)v[i].y-=min;mesh.vertices=v;mesh.RecalculateBounds();return mesh;
 }
