  var root=new GameObject("Tetrapod");root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterial=concrete;var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/Tetrapod.prefab");Object.DestroyImmediate(root);
  var strip=new GameObject("Tetrapod_ShoreStrip_20m");var rng=new System.Random(918);for(int row=0;row<3;row++)for(int i=0;i<8;i++){var g=(GameObject)PrefabUtility.InstantiatePrefab(prefab);g.name="Tetrapod_"+row+"_"+i;g.transform.SetParent(strip.transform,false);g.transform.localRotation=Quaternion.Euler((float)rng.NextDouble()*100,(float)rng.NextDouble()*360,(float)rng.NextDouble()*100);float min=float.MaxValue;foreach(var v in mesh.vertices)min=Mathf.Min(min,(g.transform.localRotation*v).y);g.transform.localPosition=new Vector3(row*1.8f,-min-row*.8f,(i-3.5f)*2.4f+(row%2)*1.1f);if(row==2)g.GetComponent<Renderer>().sharedMaterial=dark;}var stripPrefab=PrefabUtility.SaveAsPrefabAsset(strip,Root+"/Tetrapod_ShoreStrip.prefab");Object.DestroyImmediate(strip);
  Folder("Assets/_Anseong/Scenes/Sandbox");EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);var coast=(GameObject)PrefabUtility.InstantiatePrefab(stripPrefab);var single=(GameObject)PrefabUtility.InstantiatePrefab(prefab);single.name="Single_Tetrapod_Reference";single.transform.position=new Vector3(-5,0,0);
  void Box(string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.position=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(g.GetComponent<Collider>());}
  Box("Sloped_Revetment_Preview",new Vector3(2,-1.4f,0),new Vector3(9,1,25),ground);GameObject.Find("Sloped_Revetment_Preview").transform.rotation=Quaternion.Euler(0,0,-24);Box("Land_Preview",new Vector3(-10,-.55f,0),new Vector3(18,1,35),ground);Box("Sea_Preview",new Vector3(25,-1.9f,0),new Vector3(44,.1f,60),water);var camera=Camera.main;camera.transform.position=new Vector3(27,17,-26);camera.transform.LookAt(new Vector3(0,1,0));camera.fieldOfView=42;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.32f,.43f,.52f);var sun=Object.FindFirstObjectByType<Light>();sun.intensity=2;sun.transform.rotation=Quaternion.Euler(45,-40,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.65f,.68f,.72f);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_Anseong/Scenes/Sandbox/Sandbox_Tetrapod.unity");AssetDatabase.SaveAssets();int tris=mesh.triangles.Length/3;if(tris>600||prefab.GetComponentsInChildren<Rigidbody>().Length!=0||prefab.GetComponentsInChildren<Collider>().Length!=0)throw new Exception("Tetrapod validation failed");Capture(camera);Debug.Log("TETRAPOD_TEST_PASS triangles="+tris+" dimensions="+mesh.bounds.size+" stripCount=24 rigidbodies=0 colliders=0");
 }
 static void Capture(Camera camera){var rt=new RenderTexture(1200,850,24);var old=RenderTexture.active;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var image=new Texture2D(1200,850,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1200,850),0,0);image.Apply();File.WriteAllBytes("C:/Users/Admin/Documents/ChatGPT/안성제철/output/Tetrapod_Preview.png",image.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=old;Object.DestroyImmediate(image);Object.DestroyImmediate(rt);}
